export type QualitativeConfidence = 'high' | 'moderate' | 'low';
export type ReviewState = 'pending' | 'accepted' | 'rejected';

export type InterpretationFields = {
  official_report: string | null;
  ai_interpretation: string | null;
  findings: string | null;
  impression: string | null;
  limitations: string[];
};

// Generated by the server on acceptance; this is not a signed final-note attestation.
export type AcceptanceProvenance = {
  contract_version: '1.0';
  upload_id: string;
  source_sha256: string;
  prepared_integrity_token: string;
  original: InterpretationFields;
  accepted: InterpretationFields;
  edited_fields: (keyof InterpretationFields)[];
};

export type ReportItem = {
  acceptance_provenance?: AcceptanceProvenance;
  kind: string;
  time_label: string | null;
  provenance: string;
  source_reference: string | null;
  official_report: string | null;
  ai_interpretation: string | null;
  findings: string | null;
  impression: string | null;
  limitations: string[];
  privacy_checked: boolean;
  burned_in_identifiers_checked: boolean;
  routed_modules?: string[];
};

type ScoreBasis = { remaining_points: number; unconfirmed_points: number; category_depends_on_unconfirmed: boolean };

export type DiagnosticCandidate = {
  diagnosis: string;
  confidence: QualitativeConfidence;
  evidence_for: string[];
  evidence_against: string[];
  weighted_uncertainty?: string[];
  score_basis?: ScoreBasis;
  missing_discriminating_data: string[];
  source_modules: string[];
};

export type Suggestion = {
  action: string;
  priority?: 'immediate' | 'urgent' | 'routine';
  rationale?: string | null;
  source_modules?: string[];
};

export type ClinicalAssessment = {
  problem_representation: string | null;
  active_problems: string[];
  likely_diagnoses: DiagnosticCandidate[];
  differential_diagnoses: DiagnosticCandidate[];
  must_not_miss: DiagnosticCandidate[];
  suggested_tests: Suggestion[];
  treatment_suggestions: Suggestion[];
  disposition: Suggestion[];
  reassessment: Suggestion[];
  contradictions_to_clarify: string[];
  limitations: string[];
};

export type TherapySelection = {
  label: string;
  module_id: string | null;
  selection: 'diagnostic' | 'manual';
};
export type TherapyContext = { weight_kg: number | null; allergies_reviewed: boolean };
export type TherapeuticSections = {
  initial_actions: string;
  medications: string;
  monitoring: string;
  reassessment: string;
  disposition: string;
};
export type TherapeuticConfirmations = { individualized: boolean; medication_safety_reviewed: boolean };
export type TherapeuticPlan = {
  schema_version: '1.0';
  plan_id: string;
  diagnosis: TherapySelection;
  population: 'adult' | 'pediatric';
  context: TherapyContext;
  sections: TherapeuticSections;
  source_refs: { module_id: string; path: string; sha256: string; language: string }[];
  reference_text: string;
  source_revision: string;
  generated_from_digest: string;
  generation_token: string;
  suggested_content_digest: string;
  missing_requirements: string[];
  medication_safety: { status: 'REVIEW_REQUIRED'; actionable: false; required_module: 'medication-selection-safety' };
};
export type TherapeuticReview = {
  status: 'validated';
  mode: 'as_suggested' | 'edited';
  scope: 'physician_review_of_this_version';
  confirmations: TherapeuticConfirmations;
  reviewed_at: string;
  plan_digest: string;
  context_digest: string;
  validation_token: string;
};
export type TherapyIssue = { severity: string; code: string; message: string };
export type TherapyCatalogEntry = {
  id: string; title: string; populations: ('adult' | 'pediatric')[]; source_language: string;
};

export type ClinicalNotePayload = {
  schema_version: '1.0';
  language: 'pt-PT' | 'es-ES' | 'en' | 'zh';
  therapeutic_plan?: TherapeuticPlan;
  therapeutic_review?: TherapeuticReview;
  encounter: {
    encounter_id: string;
    age: { years: number | null; months: number | null };
    sex: 'female' | 'male' | 'intersex' | 'unknown';
    origin: string | null;
    transfer_status: string | null;
    functional_status: string | null;
    cognitive_status: string | null;
    living_context: string | null;
  };
  history: {
    chief_complaint: string | null;
    present_illness: string | null;
    past_medical_history: string[];
    past_surgical_history: string[];
    chronic_medications: { name: string; dose: string | null; schedule: string | null; source: string | null }[];
    medication_discrepancies: string[];
    allergies: { substance: string | null; class: string | null; reaction: string | null; severity: string | null; confirmed: boolean | null }[];
    social_history: string | null;
    baseline_status: string | null;
    source_reliability: string | null;
  };
  timeline: { time_label: string; event: string; source: string | null }[];
  exam: {
    vitals: {
      time_label: string | null;
      bp: string | null;
      hr: number | null;
      rr: number | null;
      spo2: number | null;
      oxygen: string | null;
      temperature_c: number | null;
      gcs: string | null;
      source: string | null;
    }[];
    general: string | null;
    neurologic: string | null;
    respiratory: string | null;
    cardiovascular: string | null;
    abdominal: string | null;
    skin_wounds: string | null;
    extremities: string | null;
    other: string | null;
  };
  complementary_tests: {
    laboratory: ReportItem[];
    blood_gas: ReportItem[];
    ecg: ReportItem[];
    imaging: ReportItem[];
    microbiology: ReportItem[];
    other: ReportItem[];
  };
  assessment: ClinicalAssessment;
  clinician_validation: {
    reviewed: boolean;
    reviewer_role: string | null;
    reviewed_at: string | null;
    changes_made: string | null;
  };
  privacy: {
    mode: 'clinical_pseudonymized' | 'external_anonymized';
    direct_identifiers_removed: boolean;
    free_text_screened: boolean;
    source_metadata_checked: boolean;
    burned_in_identifiers_checked: boolean;
    export_allowed: boolean;
    privacy_notes: string[];
  };
};

export type PreparedUpload = {
  api_version: string;
  upload_id: string;
  filename: string;
  mime_type: string;
  size_bytes: number;
  sha256: string;
  integrity_token: string;
  kind: string;
  kind_source?: 'explicit' | 'inferred_from_filename' | 'inferred_from_container' | 'default_unclassified';
  /** R10 Phase A: data only, not displayed. Never a verification of the real modality. */
  kind_assessment?: {
    kind_explicit: string | null;
    name_hints_matched: string[];
    modality_verification: 'not_verified' | 'metadata_consistent' | 'classifier_verified';
    kind_discordance: 'none' | 'suspected' | 'unknown' | 'demonstrable';
    suspicion_codes: string[];
  };
  route: { kind: string; target_section: keyof ClinicalNotePayload['complementary_tests']; modules: string[] };
  privacy: {
    status: 'PASS' | 'REVIEW_REQUIRED' | 'STOP';
    findings: { severity: string; code: string; message: string; path?: string }[];
    manual_file_privacy_review_required: boolean;
    burned_in_identifier_review_required: boolean;
  };
  extracted: { official_report: string | null; ai_interpretation: string | null };
  media?: {format?: string; status?: string; quality_flags?: string[]; issues?: string[]; metadata_present?: boolean} | null;
  processing: {
    status: 'text_extracted' | 'routed_external' | 'vision_interpreted' | 'vision_abstained';
    message: string;
    modules: string[];
    provider?: string | null;
    model?: string | null;
    confidence?: QualitativeConfidence | null;
    findings?: string | null;
    impression?: string | null;
    limitations?: string[];
    safety_flags?: string[];
  };
  original_retained: false;
};

export type DiagnosticApiResponse = {
  blocked: boolean;
  issues: { severity: string; code: string; message: string }[];
  signals?: { code: string; weight: number; label: string }[];
  rule_hits?: { module: string; score: number; evidence: string[]; weighted_uncertainty?: string[]; score_basis?: ScoreBasis }[];
  assessment: ClinicalAssessment | null;
  note: ClinicalNotePayload | null;
  medication_safety_gate: {
    status: 'REVIEW_REQUIRED' | 'NOT_APPLICABLE';
    actionable: boolean;
    required_module: string | null;
    message: string;
  };
};
